(α, A, B, β, ref C, ref D, out int commonRank);
Span<int> concA = stackalloc int[commonRank], concB = stackalloc int[commonRank];
Span<int> freeA = stackalloc int[A.Rank - commonRank], freeCA = stackalloc int[C.Rank - freeA.Length];
Span<int> freeB = stackalloc int[B.Rank - commonRank], freeCB = stackalloc int[C.Rank - freeB.Length];
(A.Size, A.Label, B.Size, B.Label, C.Size, C.Label, concA, concB, freeA, freeCA, freeB, freeCB);
var onHost = CudaCSharpHelpers.CheckOnHost(A, B, C, D);
var function = onHost ? new ITensor.DelegateContract<T>(CPU.Contract) : GPU.Contract;
function(α, A.Pointer, B.Pointer, β, C.Pointer, D.Pointer, A.Size.ToArray(), B.Size.ToArray(), C.Size.ToArray(), concA, concB, freeA, freeCA, freeB, freeCB);

